using UnityEngine;\nusing System.Collections.Generic;\n\n/// <summary>\nNightmare AI difficulty - near-perfect prediction and advanced tactics.\n/// This is the most challenging AI with learning capabilities.\n/// </summary>\npublic class AINightmare : AIBehavior\n{\n    private List<Vector3> positionHistory = new List<Vector3>();\n    private List<AttackType> playerAttackHistory = new List<AttackType>();\n    private float comboSuccessRate = 0.85f;\n    private float predictionAccuracy = 0.9f;\n    private int attackPhase = 1;\n    \n    public override void MakeDecision()\n    {\n        float situationScore = EvaluateSituation();\n        float distance = GetDistance();\n        \n        UpdatePhase();\n        \n        if (situationScore > 0.8f)\n        {\n            if (Random.value < comboSuccessRate)\n            {\n                ExecuteAdvancedCombo();\n            }\n            else\n            {\n                playerCharacter.Attack(SelectAttack());\n            }\n            SetState(AIState.Attacking);\n        }\n        else if (situationScore > 0.5f)\n        {\n            if (distance > 2.5f)\n            {\n                playerCharacter.Move(Vector2.right);\n                SetState(AIState.Approaching);\n            }\n            else if (opponentCharacter.IsBlocking)\n            {\n                playerCharacter.Attack(characterData.SpecialAttack);\n                SetState(AIState.Attacking);\n            }\n            else\n            {\n                ExecuteAdvancedCombo();\n                SetState(AIState.Attacking);\n            }\n        }\n        else\n        {\n            if (opponentCharacter.IsAttacking)\n            {\n                playerCharacter.Block();\n                SetState(AIState.Blocking);\n            }\n            else\n            {\n                playerCharacter.Block();\n                SetState(AIState.Blocking);\n            }\n        }\n        \n        UpdatePositionHistory();\n    }\n    \n    protected override float EvaluateSituation()\n    {\n        float score = 0.5f;\n        \n        float healthDiff = (playerCharacter.GetStats().CurrentHP - opponentCharacter.GetStats().CurrentHP) \n                          / playerCharacter.GetStats().MaxHP;\n        score += Mathf.Clamp(healthDiff * 0.6f, -0.4f, 0.4f);\n        \n        if (playerCharacter.GetStats().CanUseUltimate())\n            score += 0.3f;\n        \n        if (opponentCharacter.GetStats().CurrentStamina < 20f)\n            score += 0.25f;\n        \n        if (opponentCharacter.GetStats().CurrentHP < 0.25f * opponentCharacter.GetStats().MaxHP)\n            score += 0.2f;\n        \n        if (opponentCharacter.IsAttacking)\n            score -= 0.2f;\n        \n        return Mathf.Clamp01(score);\n    }\n    \n    protected override AttackData SelectAttack()\n    {\n        float rand = Random.value;\n        if (rand < 0.3f)\n            return characterData.LightPunch;\n        else if (rand < 0.6f)\n            return characterData.HeavyKick;\n        else if (rand < 0.85f)\n            return characterData.SpecialAttack;\n        else\n            return characterData.UltimateAttack;\n    }\n    \n    private void ExecuteAdvancedCombo()\n    {\n        int comboLength = Mathf.Min(5, (int)(playerCharacter.GetStats().CurrentStamina / 15f));\n        \n        for (int i = 0; i < comboLength; i++)\n        {\n            playerCharacter.Attack(SelectAttack());\n        }\n    }\n    \n    private void UpdatePositionHistory()\n    {\n        positionHistory.Add(opponentCharacter.transform.position);\n        if (positionHistory.Count > 10)\n            positionHistory.RemoveAt(0);\n    }\n    \n    private void UpdatePhase()\n    {\n        float healthPercent = opponentCharacter.GetStats().CurrentHP / opponentCharacter.GetStats().MaxHP;\n        \n        if (healthPercent < 0.33f)\n            attackPhase = 3;\n        else if (healthPercent < 0.66f)\n            attackPhase = 2;\n        else\n            attackPhase = 1;\n    }\n}\n"